mapper.select:
SELECT  FROM preparation_item i
WHERE i.owner_id=#{owner} AND i.status=#{status}
AND i.kind=#{kind}
AND i.title LIKE #{pattern} ESCAPE '!'

  AND i.verification=#{verification}

    AND EXISTS (SELECT 1 FROM preparation_item p WHERE p.owner_id=i.owner_id AND p.id=i.project_id
                AND p.kind='PROJECT' AND p.status='ACTIVE')


AND i.favorite=#{favorite}
AND i.project_id=#{projectId}
AND i.id > #{cursor}
ORDER BY i.id LIMIT #{limit}

SELECT id,version_number AS number,title,created_at FROM preparation_version
WHERE owner_id=#{owner} AND item_id=#{id}
AND version_number < #{before}
ORDER BY version_number DESC LIMIT #{limit}

SELECT id,version_id,decision,reason,created_at FROM preparation_fact_decision
WHERE owner_id=#{owner} AND item_id=#{id}

  AND (created_at < #{beforeTime} OR (created_at=#{beforeTime} AND id < #{beforeId}))

ORDER BY created_at DESC,id DESC LIMIT #{limit}

SELECT EXISTS (SELECT 1 FROM preparation_item i JOIN preparation_version v
  ON v.owner_id=i.owner_id AND v.item_id=i.id AND v.id=#{versionId}
  WHERE i.owner_id=#{owner} AND i.kind='EXPRESSION' AND NOT ())

mapper.update:
UPDATE preparation_item SET title=#{title},current_version_id=#{versionId},version_number=#{number},
  verification=CASE WHEN kind='FACT' THEN 'UNVERIFIED' ELSE NULL END,
  source_generation=source_generation+1,revision=revision+1,updated_at=#{now}
WHERE owner_id=#{owner} AND id=#{id} AND revision=#{expected}

UPDATE preparation_item SET status=#{status},source_generation=source_generation+1,
  revision=revision+1,updated_at=#{now}
WHERE owner_id=#{owner} AND id=#{id} AND revision=#{expected}

UPDATE preparation_item SET verification=#{verification},source_generation=source_generation+1,
  revision=revision+1,updated_at=#{now}
WHERE owner_id=#{owner} AND id=#{id} AND revision=#{expected} AND kind='FACT'
